window.OVA_CONTENT={"slug":"seccion-02-herencia-y-mejoramiento","title":"Herencia y mejoramiento agroindustrial","minutes":50,"summary":"Interpreta segregación, variación y selección sin reducir los caracteres productivos a modelos demasiado simples.","objective":"Aplicar principios de herencia al análisis responsable del mejoramiento vegetal y animal.","stages":[{"eyebrow":"Fundamento","title":"1. Alelos y segregación","reading":"En un modelo mendeliano, un individuo posee dos alelos para un gen y estos se separan durante la formación de gametos. La descendencia recibe una copia de cada progenitor.","application":"El modelo ayuda a anticipar proporciones, siempre que el rasgo estudiado se ajuste a sus supuestos.","activity":{"type":"choice","question":"¿Qué expresa la segregación?","options":["La separación de alelos al formarse los gametos","La expresión simultánea de ambos alelos en todos los tejidos","La distribución de cromosomas sin recombinación entre células somáticas"],"answer":[0],"success":"Los alelos se separan y vuelven a combinarse."}},{"eyebrow":"Lenguaje genético","title":"2. Genotipo no es fenotipo","reading":"El genotipo describe la composición genética; el fenotipo corresponde a características observables producidas por genes y ambiente. Un alelo dominante se expresa en heterocigosis, pero dominante no significa mejor ni más frecuente.","application":"Este lenguaje permite leer reportes de cruzamientos sin convertir una relación genética en un juicio de valor.","activity":{"type":"match","question":"Relaciona cada término con su significado.","pairs":[{"label":"Genotipo","value":"composicion","option":"Composición de alelos"},{"label":"Fenotipo","value":"observable","option":"Característica observable"},{"label":"Heterocigoto","value":"diferentes","option":"Dos alelos diferentes"}],"answer":["composicion","observable","diferentes"],"success":"Cada término responde una pregunta distinta."}},{"eyebrow":"Complejidad","title":"3. Rasgos productivos complejos","reading":"Rendimiento, crecimiento, eficiencia alimenticia o tolerancia al estrés suelen depender de múltiples genes y del ambiente. Por ello, una proporción mendeliana simple rara vez explica por sí sola el desempeño productivo.","application":"Los programas de mejoramiento combinan registros, evaluación de familias, condiciones de prueba y objetivos definidos.","activity":{"type":"multi","question":"¿Qué variables deben acompañar la información genética?","options":["Ambiente de evaluación","Manejo productivo durante la prueba","Registros de desempeño","Frecuencia del alelo interpretada sin fenotipo"],"answer":[0,1,2],"success":"La evidencia productiva complementa la herencia."}},{"eyebrow":"Selección","title":"4. Decidir qué mejorar","reading":"La selección debe partir de un objetivo verificable y considerar variación disponible, medición del rasgo, reproducción y evaluación de resultados. Elegir sin criterios puede reducir diversidad o desplazar características útiles.","application":"La organización debe equilibrar productividad, adaptación, calidad, costos y conservación de recursos genéticos.","activity":{"type":"order","question":"Ordena un ciclo básico de mejoramiento.","items":["Definir el objetivo","Medir variación","Seleccionar progenitores","Evaluar descendencia","Revisar resultados y diversidad"],"answer":[0,1,2,3,4],"success":"El mejoramiento es un proceso evaluado, no una compra aislada."}},{"eyebrow":"Caso aplicado","title":"5. Material vegetal para una región cálida","reading":"Un proveedor ofrece una variedad de alto rendimiento probada en clima templado. La empresa opera bajo alta temperatura y disponibilidad irregular de agua.","application":"Antes de adquirirla conviene revisar evidencia en ambientes comparables, adaptación, calidad del producto y riesgo productivo.","activity":{"type":"choice","question":"¿Cuál decisión está mejor sustentada?","options":["Realizar una prueba controlada local y comparar indicadores","Adoptar el material con base en el promedio obtenido en clima templado","Descartarlo porque ningún resultado externo puede transferirse"],"answer":[0],"success":"La adaptación debe comprobarse en el contexto de uso."}},{"eyebrow":"Variabilidad","title":"6. Diversidad como recurso de selección","reading":"La selección requiere variación heredable. Una población muy uniforme puede facilitar el manejo, pero también reducir opciones frente a nuevas plagas o cambios ambientales.","application":"Conservar bancos de germoplasma y registrar parentescos protege alternativas para ciclos futuros de mejoramiento.","visual":{"label":"Diversidad como recurso de selección","items":["Diversidad","Evaluación","Selección","Conservación"]},"activity":{"type":"choice","question":"¿Qué decisión equilibra uniformidad productiva y resiliencia?","options":["Usar material seleccionado y conservar fuentes de diversidad documentadas","Eliminar líneas de menor rendimiento antes de caracterizarlas","Mantener todos los materiales sin evaluar su desempeño"],"answer":[0],"success":"La diversidad gestionada sostiene capacidad de adaptación sin renunciar a objetivos productivos."}},{"eyebrow":"Respuesta","title":"7. Ganancia genética y condiciones de prueba","reading":"La respuesta a la selección depende de la heredabilidad, la intensidad de selección y la variación disponible. Un resultado obtenido en un ambiente no siempre se repite en otro.","application":"Los ensayos multilocales permiten separar desempeño estable de respuestas particulares al lugar.","activity":{"type":"multi","question":"¿Qué elementos fortalecen un ensayo de selección?","options":["Repeticiones y controles comparables","Ambientes representativos del uso previsto","Criterios definidos antes de observar resultados","Elegir únicamente el valor máximo de una parcela"],"answer":[0,1,2],"success":"El diseño comparativo reduce el riesgo de seleccionar por azar o por un ambiente excepcional."}},{"eyebrow":"Caso integrador","title":"8. Selección para rendimiento y tolerancia","reading":"Una asociación busca aumentar rendimiento sin perder tolerancia a sequía. Debe ponderar ambos rasgos, diversidad y estabilidad entre ambientes. Su interpretación exige comparar condiciones, escalas y registros, porque una observación aislada no demuestra causalidad ni permite predecir por sí sola el resultado productivo.","application":"Un índice de selección explícito hace visibles los compromisos entre productividad inmediata y resiliencia.","activity":{"type":"order","question":"Ordena la toma de decisión para un programa de selección.","items":["Definir rasgos y ponderaciones","Diseñar ensayos en ambientes objetivo","Medir desempeño y variabilidad","Seleccionar con el índice acordado","Validar estabilidad y conservar diversidad"],"answer":[0,1,2,3,4],"success":"El programa conecta objetivos, medición, selección y validación."}}],"number":"02","references":["Audesirk, T. et al. (2017). Biología: La vida en la tierra con fisiología. Pearson Educación.","Freeman, S. (2009). Biología. Pearson Educación.","Gutiérrez Ramírez, L. A. (2016). Los microorganismos en la agroindustria. Editorial Lasallista.","Mader, S. S. (2024). Biología. McGraw-Hill.","Velázquez Ocampo, M. P. (2020). Biología II. Cengage Learning."]};